package com.waypoint.planning.entity;
import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.time.*;import java.util.*;
@Entity @Table(name="deferral_records",schema="public") public class DeferralRecordEntity {
 @Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="deferral_id") private UUID id;@Column(name="order_id",nullable=false) private UUID orderId;@Column(name="delivery_date",nullable=false) private LocalDate deliveryDate;@Column(nullable=false) private String reason;@Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(name="constraint_type",nullable=false,columnDefinition="constraint_type") private ConstraintType constraintType;@Column(name="retry_date") private LocalDate nextPlannedDate;@Column(name="operational_note") private String operationalNote;@Column(nullable=false) private String status;@Column(name="resolved_at") private Instant resolvedAt;@Column(name="created_at",insertable=false,updatable=false) private Instant createdAt;@Column(name="updated_at",insertable=false,updatable=false) private Instant updatedAt;
 protected DeferralRecordEntity(){} public DeferralRecordEntity(UUID orderId,LocalDate deliveryDate,String reason,String constraint,LocalDate nextDate,String note){this.orderId=orderId;this.deliveryDate=deliveryDate;this.reason=reason;this.constraintType=ConstraintType.valueOf(constraint);this.nextPlannedDate=nextDate;this.operationalNote=note;this.status="ACTIVE";}
 public UUID getId(){return id;}public UUID getOrderId(){return orderId;}public LocalDate getDeliveryDate(){return deliveryDate;}public String getReason(){return reason;}public String getConstraintType(){return constraintType.name();}public LocalDate getNextPlannedDate(){return nextPlannedDate;}public boolean isNotified(){return false;}public Instant getCreatedAt(){return createdAt;}public String getStatus(){return status;}public void changeDate(LocalDate date){nextPlannedDate=date;}public void resolve(){status="RETURNED_TO_PLANNING";resolvedAt=Instant.now();}
}
